/**
 * Prism bibtex 语言组件（自制）。
 *
 * Prism 官方组件列表与 npm 生态都没有 bibtex 语法，而站内文章的论著条目
 * 使用了 ```bibtex 围栏（posts/hello-world.md、posts/roadmap.md）。
 * bibtex 语法面极窄，这里手写一份迷你语法，并且只复用 css/main.css
 * 已定义的 token 配色类（keyword / property / string / number /
 * punctuation / comment），不引入任何新 CSS —— 配色随全站主题一起走。
 *
 * 覆盖的语法：
 *   % 行注释
 *   @article / @string / @comment / @preamble 等入口类型  → keyword
 *   字段名（后随 = 的标识符，如 title = … 的 title）      → property
 *   值：{…}（允许一层花括号嵌套）与 "…"（含 \ 转义）       → string
 *   裸数字（如 year = 2026 的 2026）                       → number
 *   = { } , # 标点                                        → punctuation
 *
 * 刻意不着的部分：条目引用键（@article{key2026 的 key2026）保持原色，
 * 与字段名 / 值形成层次对比，也避免与值的花括号规则相互吞并。
 * 深于一层的花括号嵌套不匹配（退回原色），实际 BibTeX 条目极少超过一层。
 */
!function (e) {
  if (!e || !e.languages) return;
  e.languages.bibtex = {
    // 值必须紧跟在 = 之后才着 string 色：lookbehind 组不进 token，
    // 否则条目最外层花括号 @article{key, …} 会被整体吞成一个 string。
    string: {
      pattern: /(=\s*)("(?:\\.|[^"\\])*"|\{(?:\{[^{}]*\}|[^{}])*\})/,
      lookbehind: !0,
      greedy: !0
    },
    comment: /%[^\r\n]*/,
    keyword: /@[\w-]+/,
    property: /[A-Za-z][\w-]*(?=\s*=)/,
    number: /\b\d+\b/,
    punctuation: /[={},#]/
  };
}(Prism);
